import * as Engine from './engine.mjs';
import * as Portable from './portable.mjs';
import * as Store from './store.mjs';
const boot=JSON.parse(document.getElementById('harbour-boot').textContent);
const ROLE_METADATA=Engine.metadata().roles;const ROLES=ROLE_METADATA.map(r=>r.name),ROLE_FIELDS=Object.fromEntries(ROLE_METADATA.map(r=>[r.name,r.fields]));
const SECTIONS=[['workspace','Workspace & delivery'],['files','Original files & CSV'],['mapping','Role mapping'],['scope','Source scope'],['records','Records & relationships'],['operating','Operating evidence'],['finance','Financial basis'],['review','Findings & review'],['contract','Supplier templates'],['returns','Prepared output & returns'],['history','History & recovery']];
const S={key:null,ws:null,drafts:{},selection:{section:'workspace',actor:''},busy:true,conflict:null,incoming:null,page:0};
const tab=crypto.randomUUID();let priorTab=null;try{priorTab=sessionStorage.getItem('harbour-source-tab');sessionStorage.setItem('harbour-source-tab',tab);}catch{}
let draftWrites=Promise.resolve();const disabled=new WeakMap();
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=value=>String(value||'').replaceAll('_',' '),value=(object,key,fallback='')=>Object.hasOwn(object||{},key)?object[key]:fallback;
const pretty=x=>Portable.json(x),id=prefix=>prefix+'-'+crypto.randomUUID(),selected=(a,b)=>a===b?' selected':'';
function notice(text,error=false){$('harbour-notice').textContent=text;$('harbour-notice').className='notice'+(error?' error':'');}
function busy(flag){S.busy=flag;$('harbour-app').setAttribute('aria-busy',String(flag));for(const el of document.querySelectorAll('button,input,select,textarea')){if(flag){if(!disabled.has(el))disabled.set(el,el.disabled);el.disabled=true;}else if(disabled.has(el)){el.disabled=disabled.get(el);disabled.delete(el);}}}
async function act(fn){if(S.busy)return;busy(true);try{await draftWrites;await fn();}catch(error){notice(error.message||String(error),true);}finally{busy(false);}}
function on(id,fn){const node=$(id);if(node)node.addEventListener('click',event=>{event.preventDefault();act(fn);});}
function input(name,title,initial='',type='text',help=''){return '<div class="field"><label for="'+esc(name)+'">'+esc(title)+'</label><input id="'+esc(name)+'" name="'+esc(name)+'" type="'+esc(type)+'" value="'+esc(initial)+'">'+(help?'<small>'+esc(help)+'</small>':'')+'</div>';}
function area(name,title,initial='',help='',code=false){return '<div class="field"><label for="'+esc(name)+'">'+esc(title)+'</label><textarea id="'+esc(name)+'" name="'+esc(name)+'"'+(code?' class="code"':'')+'>'+esc(initial)+'</textarea>'+(help?'<small>'+esc(help)+'</small>':'')+'</div>';}
function select(name,title,options,current='',help=''){return '<div class="field"><label for="'+esc(name)+'">'+esc(title)+'</label><select id="'+esc(name)+'" name="'+esc(name)+'">'+options.map(o=>{const v=typeof o==='string'?o:o.value,t=typeof o==='string'?label(o):o.label;return '<option value="'+esc(v)+'"'+selected(v,current)+'>'+esc(t)+'</option>';}).join('')+'</select>'+(help?'<small>'+esc(help)+'</small>':'')+'</div>';}
function checks(name,title,options,current=[]){return '<fieldset><legend>'+esc(title)+'</legend>'+options.map(o=>'<label class="check"><input type="checkbox" name="'+esc(name+':'+o.value)+'" value="'+esc(o.value)+'"'+(current.includes(o.value)?' checked':'')+'><span>'+esc(o.label)+'</span></label>').join('')+'</fieldset>';}
function details(title,body){return '<details><summary>'+esc(title)+'</summary><div>'+body+'</div></details>';}
function exact(title,object){return details(title,'<pre>'+esc(pretty(object))+'</pre>');}
function formKey(formId){if(formId==='mapping-form')return formId+':'+(chooseSource()?.id||'');if(formId==='correction-form'){const source=chooseSource(),rows=source?Engine.sourceRows(S.ws,source.id).rows:[];return formId+':'+(source?.id||'')+':'+(S.selection.row||rows[S.page*50]?.id||'');}if(['review-form','contract-form','operating-form','finance-form'].includes(formId))return formId+':'+currentScope();if(formId==='return-form')return formId+':'+(currentPreparation()?.id||'');return formId;}
function form(id,body,button){return '<form id="'+esc(id)+'" data-draft="'+esc(formKey(id))+'">'+body+(button?'<div class="actions"><button class="primary" type="submit">'+esc(button)+'</button></div>':'')+'</form>';}
function card(title,body){return '<section class="card"><h2>'+esc(title)+'</h2>'+body+'</section>';}
function options(rows,title='id'){return rows.map(r=>({value:r.id,label:r[title]?r[title]+' · '+r.id:r.id}));}
function currentScope(){return S.selection.scope||S.ws?.selections.at(-1)?.id||'';}
function listIds(fields,prefix){return Object.entries(fields).filter(([key,v])=>key.startsWith(prefix+':')&&v===true).map(([key])=>key.slice(prefix.length+1));}
function parsed(text,title){try{return JSON.parse(text);}catch(error){throw Error(title+': '+error.message);}}
function capture(form){const fields={};for(const el of form.elements){if(!el.name||el.type==='file'||el.type==='submit'||el.type==='button')continue;fields[el.name]=el.type==='checkbox'?el.checked:el.value;}return fields;}
function restore(form,fields){for(const el of form.elements){if(!el.name||!Object.hasOwn(fields,el.name)||el.type==='file')continue;if(el.type==='checkbox')el.checked=fields[el.name]===true;else el.value=fields[el.name];}}
function draft(formId){return S.drafts[$(formId)?.dataset.draft||formId]||null;}
function queueDraft(formNode){
  if(!S.ws||!S.key)return;const key=S.key,fields=capture(formNode),old=draft(formNode.id),record={baseRevision:old?.baseRevision??S.ws.revision,baseHead:old?.baseHead||Portable.head(S.ws),fields};
  const formKey=formNode.dataset.draft||formNode.id;S.drafts[formKey]=record;draftWrites=draftWrites.then(()=>Store.saveDraft(key,tab,formKey,record)).catch(error=>notice('Unfinished values remain on this page; browser saving failed: '+error.message,true));
}
function bindDrafts(){
  for(const node of document.querySelectorAll('form[data-draft]')){
    if(S.drafts[node.dataset.draft])restore(node,S.drafts[node.dataset.draft].fields);
    node.addEventListener('input',()=>queueDraft(node));node.addEventListener('change',()=>queueDraft(node));
    const record=draft(node.id);if(record&&record.baseHead!==Portable.head(S.ws)){const p=document.createElement('p');p.className='inline-note';p.textContent='This unfinished form began at revision '+record.baseRevision+'. Review its values against the current source before submitting.';node.prepend(p);const button=document.createElement('button');button.type='button';button.textContent='Keep these values against current revision';button.addEventListener('click',()=>act(async()=>{record.baseRevision=S.ws.revision;record.baseHead=Portable.head(S.ws);record.fields=capture(node);await Store.saveDraft(S.key,tab,node.dataset.draft,record);render();notice('The unchanged unfinished values now reference the current revision.');}));p.after(button);}
  }
}
function bindSubmit(formId,fn){const node=$(formId);if(!node)return;node.addEventListener('submit',event=>{event.preventDefault();if(S.busy)return;const fields=capture(node),files=Object.fromEntries([...node.elements].filter(el=>el.type==='file').map(el=>[el.name,Array.from(el.files)]));act(()=>fn(fields,files,formId));});}
async function chooseSection(section){S.selection.section=section;S.page=0;await saveSelectionDraft();render();}
async function saveSelectionDraft(){if(!S.ws)return;await Store.saveDraft(S.key,tab,'$selection',{baseRevision:S.ws.revision,baseHead:Portable.head(S.ws),fields:{value:pretty(S.selection)}});}
async function useCopy(key,incomingDrafts={},incomingSelection=null){
  const row=await Store.readCopy(key);if(!row)throw Error('This saved browser copy is missing. Open the complete working file.');Engine.validateWorkspace(row.workspace);S.key=key;S.ws=row.workspace;S.conflict=null;S.selection={section:'workspace',actor:'',...row.selection,...(incomingSelection||{})};
  if(priorTab&&priorTab!==tab)await Store.mergeDrafts(key,tab,await Store.readDrafts(key,priorTab));
  S.drafts=await Store.mergeDrafts(key,tab,incomingDrafts);
  if(S.drafts.$selection){try{S.selection={...S.selection,...JSON.parse(S.drafts.$selection.fields.value)};}catch{}}
  S.page=0;render();if(Object.keys(incomingDrafts||{}).length)notice('Received unfinished values are retained; any differing current writing remains available as a separate lineage in History & recovery.');
}
async function readBinary(file,max=Engine.LIMITS.fileBytes){if(!file)throw Error('Select the complete original file.');if(file.size>max)throw Error('The selected complete file exceeds '+Math.floor(max/1048576)+' MiB.');const bytes=new Uint8Array(await file.arrayBuffer());return {bytes,base64:Engine.encodeBase64(bytes)};}
function readText(bytes){return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes);}
function download(name,body,type='application/octet-stream'){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function record(){return Portable.recovery(S.ws,S.drafts,S.selection,S.key);}
async function mutate(name,input,formId){
  if(!S.ws)throw Error('Open a workspace first.');const submitted=formId&&draft(formId)?{[$(formId)?.dataset.draft||formId]:draft(formId)}:{};
  if(formId&&draft(formId)&&draft(formId).baseHead!==Portable.head(S.ws))throw Error('Review this unfinished form against the current revision using its visible control.');
  const actor=String(S.selection.actor||'');if(!actor.trim())throw Error('Enter the named operator above this section.');
  const before=S.ws,expectedHead=Portable.head(before),operation={operationId:id(name),expectedRevision:before.revision,at:new Date().toISOString(),actor,...input};
  const fn=Engine[name];if(typeof fn!=='function')throw Error('The selected complete engine does not expose '+name+'.');
  const result=fn(before,operation);
  try{const saved=await Store.commitCopy({key:S.key,expectedHead,workspace:result.workspace,selection:S.selection,tab,submitted});S.ws=saved.workspace;for(const key of Object.keys(submitted))delete S.drafts[key];S.conflict=null;return result;}
  catch(error){if(error.code==='COPY_CONFLICT'){const branch=id('harbour-copy');await Store.createCopy(branch,result.workspace,S.selection,tab,S.drafts);S.conflict={branch,original:S.key,operation:result.receipt};notice('Another tab saved the original. Your complete proposed operation and unfinished writing are preserved in independent copy '+branch+'.',true);render();}throw error;}
}
function table(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function missing(v){return v===undefined||v===null?'<span class="cell-empty">Missing position</span>':v===''?'<span class="cell-empty">Present empty string</span>':esc(v);}
function render(){
  if(!views[S.selection.section])S.selection.section='workspace';
  $('workspace-heading').textContent=S.ws?S.ws.title+' · '+S.ws.id:'Complete original records, evidence and receiving';$('workspace-revision').textContent=S.ws?'Revision '+S.ws.revision+' · browser copy '+S.key:'No workspace selected';
  $('harbour-nav').innerHTML=SECTIONS.map(([key,title])=>'<button type="button" data-section="'+key+'" aria-current="'+(S.selection.section===key)+'"'+(!S.ws&&key!=='workspace'?' disabled':'')+'>'+title+'</button>').join('');
  for(const button of document.querySelectorAll('[data-section]'))button.addEventListener('click',()=>act(()=>chooseSection(button.dataset.section)));
  const host=$('harbour-app');host.innerHTML=(S.ws?'<section class="card"><div class="grid">'+input('current-operator','Named operator',S.selection.actor||'','text','Retained on each new attributed operation.')+'<div><p>Permission and history rows are source assertions. Supplier interpretation and actual returned evidence remain explicit.</p></div></div></section>':'')+(S.conflict?card('A competing edit was preserved','<p>Both complete branches remain saved.</p><div class="actions"><button id="open-conflict">Open my preserved branch</button><button id="reload-current">Open current original copy</button></div>'):'')+(S.incoming?incomingView():'')+views[S.selection.section||'workspace']();
  const actor=$('current-operator');if(actor)actor.addEventListener('change',()=>{S.selection.actor=actor.value;saveSelectionDraft().catch(e=>notice(e.message,true));});
  bindDrafts();bindCommon();binders[S.selection.section||'workspace']();if(S.busy)busy(true);
}
const views={},binders={};
function bindCommon(){on('open-conflict',()=>useCopy(S.conflict.branch));on('reload-current',()=>useCopy(S.conflict.original));on('receive-independent',async()=>{const incoming=S.incoming.record,key=id('harbour-copy');await Store.createCopy(key,incoming.workspace,incoming.selection,tab,incoming.drafts);S.incoming=null;await useCopy(key);});on('keep-current',async()=>{S.incoming=null;render();});on('receive-descendant',async()=>{const incoming=S.incoming.record,expectedHead=S.incoming.expectedHead;await Store.commitCopy({key:S.key,expectedHead,workspace:incoming.workspace,selection:incoming.selection,tab,submitted:{}});await Store.mergeDrafts(S.key,tab,incoming.drafts);S.incoming=null;await useCopy(S.key);notice('Received the complete descendant. Current and differing incoming unfinished values remain recoverable in History & recovery.');});}
function incomingView(){const relation=S.incoming.relation;return card('Received complete working file','<p>Selected file: '+esc(S.incoming.filename)+'. Relationship to this copy: <strong>'+esc(label(relation))+'</strong>.</p><p>Original saved branches and unfinished writing stay recoverable.</p><div class="actions"><button id="receive-independent">Keep as independent copy</button>'+(relation==='incoming_descendant'?'<button id="receive-descendant">Receive newer descendant into this copy</button>':'')+'<button id="keep-current">Continue current copy</button></div>');}
views.workspace=()=>card(S.ws?'Complete working delivery':'Open or create complete work',form('open-work','<div class="field"><label for="open-file">Complete workspace or recovery JSON</label><input id="open-file" name="open-file" type="file" accept=".json"></div>','Open complete file')+(!S.ws?form('create-work',input('workspace-title','Workspace title')+input('workspace-id','Original workspace ID',id('harbour-workspace')),'Create workspace'):'<div class="facts">'+[['Original files',S.ws.files.length],['CSV sources',S.ws.sources.length],['Revision',S.ws.revision],['Mappings',S.ws.mappings.length]].map(([name,count])=>'<div class="fact"><strong>'+count+'</strong><span>'+name+'</span></div>').join('')+'<div class="actions"><button id="top-json">Download complete working JSON</button><button id="top-html">Download working HTML</button><button id="top-zip">Download whole ZIP</button><button id="engine-json">Download engine workspace</button></div><p>The complete working file includes source history, current selection and this tab’s unfinished forms. The whole ZIP also contains every original byte, report and maintained source file.</p>'))+card('Saved browser copies','<div id="copy-list">Loading saved copies…</div>');
binders.workspace=()=>{
  Store.listCopies().then(rows=>{if(!$('copy-list'))return;$('copy-list').innerHTML=rows.length?table(['Saved work','Revision','Updated','Open'],rows.map(row=>[esc(row.workspace.title)+'<br><small>'+esc(row.key)+'</small>',String(row.revision),esc(row.updatedAt),'<button type="button" data-copy="'+esc(row.key)+'">Open copy</button>'])):'<p>No saved copies in this browser.</p>';for(const b of document.querySelectorAll('[data-copy]'))b.onclick=()=>act(()=>useCopy(b.dataset.copy));if(S.busy)busy(true);}).catch(e=>notice(e.message,true));
  bindSubmit('create-work',async fields=>{const workspace=Engine.createWorkspace({id:fields['workspace-id'],title:fields['workspace-title'],createdAt:new Date().toISOString()}),key=id('harbour-copy');await Store.createCopy(key,workspace,{});await useCopy(key);notice('The complete workspace is saved in this browser.');});
  bindSubmit('open-work',async(fields,files)=>{const file=files['open-file'][0];if(!file||file.size>Portable.RECOVERY_BYTES)throw Error('Select one complete working file within 128 MiB.');const incoming=Portable.parseRecovery(readText((await readBinary(file,Portable.RECOVERY_BYTES)).bytes));if(!S.ws){const key=id('harbour-copy');await Store.createCopy(key,incoming.workspace,incoming.selection,tab,incoming.drafts);await useCopy(key);return;}S.incoming={record:incoming,filename:file.name,relation:Portable.compare(S.ws,incoming.workspace),expectedHead:Portable.head(S.ws)};render();});
  on('top-json',async()=>download('Harbour_Working_Recovery.json',pretty(record()),'application/json'));
  on('top-html',async()=>download('Harbour_Source_Workspace.html',Portable.workingHTML(boot.source,record()),'text/html'));
  on('top-zip',async()=>download('Harbour_Complete_Workspace.zip',Portable.zipBytes(Portable.completeFiles(boot.source,record())),'application/zip'));
  on('engine-json',async()=>download('Harbour_Workspace.json',Engine.exportWorkspace(S.ws),'application/json'));
};
views.files=()=>card('Retain a complete original',form('import-file','<div class="grid"><div class="field"><label for="original-file">Complete original file</label><input id="original-file" name="original-file" type="file"></div>'+select('file-representation','Source representation',['original','authored-transcription','authored-example'],'original')+'</div>'+input('file-id','Original file binding ID, if explicitly supplied','','text','Use the exact ID required by document records, or leave blank for an automatic immutable file identity.')+input('file-purpose','Source context / purpose')+input('file-url','Original source URL, when supplied')+'<p>PDF, SQL, workbook and evidence files remain complete originals. Select an actual CSV export below to map records.</p>','Retain original file'))+card('Receive every CSV row',form('import-csv','<div class="field"><label for="csv-file">Complete UTF-8 CSV</label><input id="csv-file" name="csv-file" type="file" accept=".csv,.txt"></div><div class="grid">'+select('csv-side','Source role',['source','target','reference'])+select('csv-role','Neutral migration role',ROLES)+'</div>'+select('csv-representation','Source representation',['original','authored-transcription','authored-example'],'original')+input('csv-file-id','Original file binding ID, if explicitly supplied')+input('csv-purpose','Source context / purpose')+input('csv-url','Original source URL, when supplied')+'<p>Ordered duplicate headings, exact strings, short rows and original quoting are retained. These role names describe this migration workspace.</p>','Receive CSV'))+card('Every original file',table(['Filename','Bytes','Purpose','Original'],S.ws.files.map(file=>[esc(file.filename||file.name||file.id),String(file.bytes??''),esc(file.purpose||''),'<button type="button" data-original="'+esc(file.id)+'">Download full original</button>'])))+card('Retained CSV sources',table(['Source','Role / side','Rows','Identity'],S.ws.sources.map(source=>[esc(source.filename||source.id),esc(source.role)+' / '+esc(source.side),String(source.rowCount??source.rows?.length??''),esc(source.id)])));
binders.files=()=>{
  bindSubmit('import-file',async(fields,files,formId)=>{const file=files['original-file'][0],body=await readBinary(file);const result=await mutate('importFile',{...(fields['file-id']?{fileId:fields['file-id']}:{}),filename:file.name,mimeType:file.type||'application/octet-stream',purpose:fields['file-purpose'],sourceUrl:fields['file-url'],representation:fields['file-representation'],base64:body.base64},formId);render();notice('Retained complete original '+result.receipt.result.fileId+'.');});
  bindSubmit('import-csv',async(fields,files,formId)=>{const file=files['csv-file'][0],body=await readBinary(file);const result=await mutate('importCsv',{...(fields['csv-file-id']?{fileId:fields['csv-file-id']}:{}),representation:fields['csv-representation'],filename:file.name,purpose:fields['csv-purpose'],sourceUrl:fields['csv-url'],side:fields['csv-side'],role:fields['csv-role'],text:readText(body.bytes)},formId);S.selection.source=result.receipt.result.sourceId;render();notice('Received '+result.receipt.result.rowCount+' complete rows.');});
  for(const button of document.querySelectorAll('[data-original]'))button.onclick=()=>act(async()=>{const file=S.ws.files.find(f=>f.id===button.dataset.original);download(file.filename||file.name||'Original.bin',Engine.decodeBase64(file.base64),file.mimeType||file.mediaType||'application/octet-stream');});
};

function chooseSource(){return S.ws.sources.find(row=>row.id===S.selection.source)||S.ws.sources[0]||null;}
function sourceChooser(id,title='Original CSV source'){return select(id,title,options(S.ws.sources.map(s=>({...s,display:(s.role||'')+' · '+s.side+' · '+(s.filename||s.id)})),'display'),chooseSource()?.id||'');}
function columnOptions(headers,blank=true){return [...(blank?[{value:'',label:'Not selected'}]:[]),...headers.map((name,index)=>({value:String(index),label:index+' · '+(name===''?'(empty heading)':name)}))];}
function bindSourceChooser(id){const node=$(id);if(node)node.onchange=()=>act(async()=>{S.selection.source=node.value;S.page=0;await saveSelectionDraft();render();});}
views.mapping=()=>{
  const source=chooseSource();if(!source)return card('Role mapping','<p>Receive a complete CSV source first.</p>');
  const data=Engine.sourceRows(S.ws,source.id),fields=ROLE_FIELDS[source.role]||['label','status'];return card('Explicit original mapping',sourceChooser('mapping-source')+'<p>Source role: <strong>'+esc(source.role)+'</strong>. Select every opaque key part and each actual column occurrence. The original source retains unmapped fields.</p>'+form('mapping-form',input('mapping-namespace','Original namespace')+checks('mapping-key','Compound key columns',data.headers.map((name,i)=>({value:String(i),label:i+' · '+name})),[])+fields.map(name=>select('field:'+name,label(name),columnOptions(data.headers))).join('')+area('mapping-extra','Additional field selectors','{}','Map additional field labels to {"column": 0} or {"constant": "exact value"}.',true)+area('mapping-references','Explicit references','[]','Each reference declares its ID, purpose, relationship, target role/namespace, key selectors and required flag. No relationship is inferred from a heading.',true)+area('mapping-note','Mapping reason and source context'),'Save mapping edition'))+card('All mapping editions',S.ws.mappings.length?table(['Mapping','Source','Namespace','Original definition'],S.ws.mappings.map(mapping=>[esc(mapping.id),esc(mapping.sourceId),esc(mapping.namespace),exact('Complete mapping',mapping)])):'<p>No mapping selected yet.</p>');
};
binders.mapping=()=>{bindSourceChooser('mapping-source');bindSubmit('mapping-form',async(fields,unused,formId)=>{const source=chooseSource(),mapped=parsed(fields['mapping-extra'],'Additional fields');for(const [name,column]of Object.entries(fields))if(name.startsWith('field:')&&column!==''){const key=name.slice(6);if(Object.hasOwn(mapped,key))throw Error('Select '+key+' once.');mapped[key]={column:Number(column)};}const result=await mutate('saveMapping',{sourceId:source.id,namespace:fields['mapping-namespace'],keyColumns:listIds(fields,'mapping-key').map(Number),fields:mapped,references:parsed(fields['mapping-references'],'References'),note:fields['mapping-note']},formId);render();notice('Saved original mapping '+result.receipt.result.mappingId+'.');});};
function basisFields(name,title){return '<fieldset><legend>'+esc(title)+'</legend>'+select(name+'-status','Declared interpretation',['unconfirmed','source-declared'],'unconfirmed')+checks(name+'-file','Retained original policy / evidence files',options(S.ws.files.map(f=>({...f,display:f.filename||f.name||f.id})),'display'),[])+area(name+'-note','Original semantics and completeness statement')+(name==='evidence'?area('evidence-external','Explicit external-only document declarations','[]','Only use under source-declared evidence with retained basis files. Each declaration has namespace, exact key parts, reason and locator. No original bytes are claimed for these records.',true):'')+'</fieldset>';}
views.scope=()=>card('Freeze the complete selected population','<p>Declare all nineteen neutral roles and the selected original mappings. Missing roles and unconfirmed permission/history meaning stay visible. Source assertions are not local access rules.</p>'+form('scope-form',checks('scope-mapping','Selected complete mappings',S.ws.mappings.map(m=>({value:m.id,label:m.id+' · '+m.namespace+' · '+m.sourceId})),[])+checks('scope-file','Supporting original files',options(S.ws.files.map(f=>({...f,display:f.filename||f.name||f.id})),'display'),[])+'<div class="grid">'+ROLES.map(role=>'<fieldset><legend>'+esc(label(role))+'</legend>'+select('role:'+role,'Coverage',['included','not-supplied','not-applicable'],'not-supplied')+area('reason:'+role,'Coverage reason')+'</fieldset>').join('')+'</div>'+area('scope-acyclic','Only declared acyclic relationship labels','[]','Use the actual source contract. Other graph cycles remain ordinary retained relationships.',true)+basisFields('permission','Permission source basis')+basisFields('history','History source basis')+basisFields('evidence','Evidence source basis')+area('scope-external','Explicit external relationship endpoints','[]','Each declaration binds exact namespace, role, key parts, selected source files, locator and reason. It does not invent a local record or target key.',true)+area('scope-note','Population, cutoff and full scope reason'),'Save complete scope'))+card('Saved scope editions',S.ws.selections.length?table(['Scope','Mappings','Original selection'],S.ws.selections.map(selection=>[esc(selection.id),String(selection.mappingIds?.length??''),exact('Complete scope',selection)])):'<p>No frozen scope yet.</p>');
binders.scope=()=>bindSubmit('scope-form',async(fields,unused,formId)=>{const roles=Object.fromEntries(ROLES.map(role=>[role,{status:fields['role:'+role],reason:fields['reason:'+role]}])),basis=name=>({status:fields[name+'-status'],sourceFileIds:listIds(fields,name+'-file'),note:fields[name+'-note'],...(name==='evidence'&&parsed(fields['evidence-external']||'[]','External-only evidence').length?{externalReferences:parsed(fields['evidence-external'],'External-only evidence')}:{})});const result=await mutate('saveSelection',{mappingIds:listIds(fields,'scope-mapping'),fileIds:listIds(fields,'scope-file'),roles,declaredAcyclicRelations:parsed(fields['scope-acyclic'],'Acyclic declarations'),permissionBasis:basis('permission'),historyBasis:basis('history'),evidenceBasis:basis('evidence'),externalReferences:parsed(fields['scope-external']||'[]','External relationship endpoints'),note:fields['scope-note']},formId);S.selection.scope=result.receipt.result.selectionId;render();notice('Saved complete scope '+S.selection.scope+'.');});
function scopeChooser(name){return select(name,'Frozen source scope',options(S.ws.selections),currentScope());}
function bindScopeChooser(name){const node=$(name);if(node)node.onchange=()=>act(async()=>{S.selection.scope=node.value;S.page=0;await saveSelectionDraft();render();});}
function analysis(){return currentScope()?Engine.analyse(S.ws,{selectionId:currentScope()}):null;}

function selectedMappings(){const scope=S.ws.selections.find(s=>s.id===currentScope());return (scope?.mappingIds||[]).map(id=>S.ws.mappings.find(m=>m.id===id)).filter(Boolean);}
function mappingRole(mapping){return S.ws.sources.find(s=>s.id===mapping.sourceId)?.role||'';}
function policyFiles(name){const scope=S.ws.selections.find(s=>s.id===currentScope()),ids=new Set(scope?.fileIds||[]);for(const m of selectedMappings()){const s=S.ws.sources.find(s=>s.id===m.sourceId);if(s)ids.add(s.fileId);}return checks(name,'Retained selected policy / basis originals',S.ws.files.filter(f=>ids.has(f.id)).map(f=>({value:f.id,label:(f.filename||f.id)+' · '+f.id})),[]);}
function mappedCatalogue(){return table(['Original mapping','Role / namespace','Explicit fields','Declared references'],selectedMappings().map(m=>[esc(m.id),esc(mappingRole(m))+' / '+esc(m.namespace),Object.keys(m.fields).map(esc).join(', '),exact('Complete mapped references',m.references)]));}
function operatingSkeleton(){return selectedMappings().filter(m=>['applications','offers','agreements','vessels','decisions'].includes(mappingRole(m))).map(m=>({mappingId:m.id,dateFields:{},codeMeanings:{},requiredByType:[],dateOrders:[],dimensions:[],localContacts:[],waitingDecisions:[]}));}
function financialSkeleton(){return selectedMappings().filter(m=>['charges','payments','allocations'].includes(mappingRole(m))).map(m=>({mappingId:m.id,amountField:'',currencyField:'',accountField:'',periodField:'',entryTypeField:'',entryTypes:[]}));}
function profileIssues(profile){return table(['Severity','Finding','Source identity','Complete evidence'],(profile?.issues||[]).map(i=>[esc(i.severity),esc(i.code)+'<br>'+esc(i.message),esc(i.key||i.role||''),exact('Original operands and witnesses',i)]));}
function profileRows(profile){return details('Every assessed original record',table(['Original identity','Explicit mapped values','Original witnesses'],(profile?.rows||[]).slice(0,100).map(r=>[identityText(r.identity)||esc(r.key),exact('All mapped values',r.fields||r.values||r),exact('Whole source witnesses',r.witnesses||r)]))+'<p>Up to100 rows are shown in this summary; the complete profile analysis and readable report retain every selected record.</p>'+exact('Full assessed population',profile?.rows||[]));}
function operatingPanel(a){const p=a.operating;return '<p>Operating evidence: <strong>'+esc(p?.status||'UNCONFIRMED')+'</strong>. These checks preserve original evidence; they do not issue suitability, allocation, navigation, permit or withdrawal decisions.</p>'+profileIssues(p)+profileRows(p)+exact('Complete operating profile and assessment',p||{});}
function financePanel(a){
 const p=a.finance,cell=v=>esc(v===null||v===undefined?'—':typeof v==='object'?pretty(v):String(v));
 const totals=table(['Namespace','Account','Currency','Period','Role','Original entry code','Exact selected total','Contributing record keys','Unqualified records'],(p?.totals||[]).map(r=>[r.namespace,r.account,r.currency,r.period,r.role,r.entryType,r.amount,r.recordKeys,r.unqualifiedRecords].map(cell)));
 const allocations=table(['Original allocation key','Charge key','Payment key','Declared amount','State','Original witnesses'],(p?.allocations||[]).map(r=>[r.key,r.chargeKey,r.paymentKey,r.amount,r.status,r.witnesses].map(cell)));
 const residuals=table(['Record key','Role','Namespace','Account','Currency','Period','Amount','Selected allocations','Remaining amount','Qualification','Complete coverage'],(p?.residuals||[]).map(r=>[r.key,r.role,r.namespace,r.account,r.currency,r.period,r.amount,r.selectedAllocatedAmount,r.residual,r.status,r.coverage].map(cell)));
 return '<p>Financial basis: <strong>'+esc(p?.status||'UNCONFIRMED')+'</strong>. Amounts are exact original decimals under the declared sign and partition basis. Selected totals are not an inferred debtor balance.</p>'+profileIssues(p)+'<h3>Every selected-record total</h3>'+totals+'<h3>Original allocation relationships</h3>'+allocations+'<h3>Qualified remaining amounts</h3>'+residuals+'<p>A missing remaining amount stays unconfirmed. Only the exact retained completeness declaration can qualify a residual.</p>'+profileRows(p)+details('Complete original financial profile and assessment',exact('All declared fields, rows, totals, allocations, residuals and findings',p||{}));
}
views.operating=()=>{
 if(!S.ws.selections.length)return card('Operating evidence','<p>Save the complete source scope first. Original harbour decisions and policy files must remain attributable.</p>');
 const a=analysis();return card('Source-bound harbour operating evidence',scopeChooser('operating-scope')+operatingPanel(a))+
 card('Retain an explicit operating profile',mappedCatalogue()+form('operating-form',input('operating-title','Profile title')+policyFiles('operating-file')+
 area('operating-bindings','Exact mapping bindings',pretty(operatingSkeleton()),'Each binding names the actual mapping. Declare dateFields, codeMeanings, requiredByType, dateOrders, dimensions, localContacts and waitingDecisions; empty arrays mean that check is not declared.',true)+
 details('Supported binding contract','<p>Dates declare date-only or offset-timestamp. Compare only declared fields with the same format. Codes have explicit value/meaning pairs. A local-contact rule names its application condition, contact reference, consenting values and original evidence reference. A reinstatement rule names the actual decision flag and linked application date. Full examples and every field are in the included API guide.</p><pre>'+esc(pretty({mappingId:'SELECT_ORIGINAL_MAPPING',dateFields:{},codeMeanings:{},requiredByType:[],dateOrders:[],dimensions:[],localContacts:[],waitingDecisions:[]}))+'</pre>')+
 area('operating-note','Policy applicability, authority and unresolved interpretation')+
 '<p>Do not infer travel eligibility from geography, synthesise offer deadlines, convert dimensions or turn a source review into an authority decision. Later source changes require a new profile.</p>','Save operating profile'))+
 card('Every original operating edition',table(['Profile','Source scope','Original complete policy'],(S.ws.operatingProfiles||[]).map(p=>[esc(p.id),esc(p.selectionId),exact('Complete original profile',p)])));
};
binders.operating=()=>{bindScopeChooser('operating-scope');bindSubmit('operating-form',async(fields,unused,formId)=>{const result=await mutate('saveOperatingProfile',{selectionId:currentScope(),title:fields['operating-title'],sourceFileIds:listIds(fields,'operating-file'),bindings:parsed(fields['operating-bindings'],'Operating bindings'),note:fields['operating-note']},formId);render();notice('Saved source-bound operating profile '+result.receipt.result.operatingProfileId+'. Review this exact profile before preparing a new target edition.');});};
views.finance=()=>{
 if(!S.ws.selections.length)return card('Financial basis','<p>Save the complete source scope first. No opening balance, source sign convention or complete period is inferred.</p>');
 const a=analysis();return card('Declared source financial controls',scopeChooser('finance-scope')+financePanel(a))+
 card('Retain the original financial basis',mappedCatalogue()+form('finance-form',input('finance-title','Financial profile title')+policyFiles('finance-file')+
 area('finance-amount-basis','Amount basis and period boundaries')+area('finance-sign-basis','Charge, receipt, credit, refund and allocation sign convention')+
 area('finance-bindings','Exact financial field and code bindings',pretty(financialSkeleton()),'Choose actual mapped amount, currency, account, period and entry-type fields. Explicit entryTypes are {value,signMultiplier:1|-1}. No fields or sign codes are guessed.',true)+
 area('finance-namespaces','Permitted cross-namespace triples','[]','Each row is {allocation,charge,payment}. Otherwise exact namespaces must agree.',true)+
 area('finance-periods','Permitted cross-period triples','[]','Each row is {allocation,charge,payment}. This permits a declared comparison, not a period roll-forward.',true)+
 area('finance-coverage','Complete-population attestations','[]','Each row declares namespace, account, currency, period, chargesComplete, paymentsComplete, allocationsComplete, openingItemsComplete, sourceFileIds and note. Without complete evidence residuals remain unconfirmed.',true)+
 area('finance-note','Source accounting interpretation and unresolved checks')+
 '<p>Retain whole source amounts and their normalized control amounts. No public tariff calculation, currency conversion, payment collection or financial signoff is performed here.</p>','Save financial profile'))+
 card('Every original financial edition',table(['Profile','Source scope','Original complete basis'],(S.ws.financialProfiles||[]).map(p=>[esc(p.id),esc(p.selectionId),exact('Complete original profile',p)])));
};
binders.finance=()=>{bindScopeChooser('finance-scope');bindSubmit('finance-form',async(fields,unused,formId)=>{const result=await mutate('saveFinancialProfile',{selectionId:currentScope(),title:fields['finance-title'],sourceFileIds:listIds(fields,'finance-file'),amountBasis:fields['finance-amount-basis'],signBasis:fields['finance-sign-basis'],bindings:parsed(fields['finance-bindings'],'Financial bindings'),permittedNamespaceTriples:parsed(fields['finance-namespaces'],'Namespace triples'),permittedPeriodTriples:parsed(fields['finance-periods'],'Period triples'),coverage:parsed(fields['finance-coverage'],'Coverage declarations'),note:fields['finance-note']},formId);render();notice('Saved source-bound financial profile '+result.receipt.result.financialProfileId+'. Review this exact basis before preparing a new target edition.');});};

views.records=()=>{
  const source=chooseSource();if(!source)return card('Complete original records','<p>Receive a CSV source first.</p>');
  const data=Engine.sourceRows(S.ws,source.id),perPage=50,start=S.page*perPage,rows=data.rows.slice(start,start+perPage),rowId=S.selection.row||rows[0]?.id,row=data.rows.find(r=>r.id===rowId);
  let html=card('Every retained row',sourceChooser('records-source')+'<p>Rows '+(data.rows.length?start+1:0)+'–'+Math.min(start+perPage,data.rows.length)+' of '+data.rows.length+'. Original header positions are shown even when names repeat.</p>'+table(['Row',...data.headers.map((name,i)=>i+' · '+name),'Review'],rows.map(row=>[esc(row.record??row.id),...data.headers.map((_,i)=>missing(row.cells[i])),'<button type="button" data-record="'+esc(row.id)+'">Inspect / correct</button>']))+'<div class="actions"><button id="records-previous"'+(S.page===0?' disabled':'')+'>Previous complete page</button><button id="records-next"'+(start+perPage>=data.rows.length?' disabled':'')+'>Next complete page</button></div>');
  if(row){const column=S.selection.column??0,actual=row.cells[column],file=S.ws.files.find(f=>f.id===source.fileId),original=Engine.parseCsv(Engine.utf8Text(Engine.decodeBase64(file.base64))).rows[row.record-2],width=Math.max(data.headers.length,original.length,row.cells.length);html+=card('Original row and attributed correction',table(['Original position / heading','Original exact value','Current exact value'],Array.from({length:width},(_,i)=>[i+' · '+esc(data.headers[i]??'(outside original header)'),missing(original[i]),missing(row.cells[i])]))+exact('Complete retained row and original cells',{...row,originalCells:original})+form('correction-form','<p>Selected original row: <strong>'+esc(row.id)+'</strong>. A missing trailing cell is added one position at a time; earlier values remain in history.</p>'+select('correction-column','Original column position',columnOptions(data.headers,false),String(column))+area('correction-value','Replacement exact text',actual===undefined?'':actual,'An empty value here is an intentional present empty string.')+area('correction-reason','Reason for this exact correction'),'Save attributed correction'));}
  const a=analysis();if(a)html+=card('Selected source relationships',scopeChooser('records-scope')+'<div class="facts">'+[['Records',a.summary.records],['Relationships',a.summary.relationships],['Documents',a.summary.documents]].map(([name,count])=>'<div class="fact"><strong>'+esc(count)+'</strong><span>'+name+'</span></div>').join('')+'</div>'+sourceStructure(a));return html;
};
binders.records=()=>{
  bindSourceChooser('records-source');bindScopeChooser('records-scope');
  on('records-previous',async()=>{S.page=Math.max(0,S.page-1);render();});on('records-next',async()=>{S.page++;render();});
  for(const button of document.querySelectorAll('[data-record]'))button.onclick=()=>act(async()=>{S.selection.row=button.dataset.record;S.selection.column=0;await saveSelectionDraft();render();});
  const column=$('correction-column');if(column)column.onchange=()=>{S.selection.column=Number(column.value);const row=Engine.sourceRows(S.ws,chooseSource().id).rows.find(r=>r.id===(S.selection.row||Engine.sourceRows(S.ws,chooseSource().id).rows[S.page*50]?.id));$('correction-value').value=row?.cells[Number(column.value)]??'';queueDraft($('correction-form'));};
  bindSubmit('correction-form',async(fields,unused,formId)=>{const source=chooseSource(),rows=Engine.sourceRows(S.ws,source.id).rows,row=rows.find(r=>r.id===(S.selection.row||rows[S.page*50]?.id)),column=Number(fields['correction-column']);if(!row)throw Error('Select an actual original row.');if(column>row.cells.length)throw Error('Repair the next missing position first; intervening values are not inferred.');await mutate('saveCorrection',{sourceId:source.id,rowId:row.id,column,expectedValue:column<row.cells.length?row.cells[column]:null,value:fields['correction-value'],reason:fields['correction-reason']},formId);render();notice('Saved exact source correction; prior scopes retain their original selection.');});
};

function identityText(identity){return identity?esc(identity.namespace)+' / '+esc(identity.role)+' / '+esc(JSON.stringify(identity.parts)):'';}
function fullCells(headers,cells){return table(['Position / original heading','Exact text'],headers.map((h,i)=>[i+' · '+esc(h),missing(cells[i])]));}
function recordSummary(records){return table(['Original identity','Mapped fields','References','Original witnesses'],records.slice(0,50).map(r=>[identityText(r.identity),table(['Field','Exact value'],Object.entries(r.fields).map(([k,v])=>[esc(k),missing(v)])),(r.references||[]).map(v=>esc(v.relation)+' → '+esc(v.targetNamespace)+' / '+esc(v.targetRole)+' / '+esc(JSON.stringify(v.parts))).join('<br>'),exact('Every original row for this record',r.witnesses)]))+(records.length>50?'<p>Showing 50 of '+records.length+' records in this overview. The original CSV row controls and complete source report retain the full population.</p>':'');}
function sourceStructure(a){
 return details('Operating evidence and recorded authority decisions',operatingPanel(a))+details('Declared financial basis and control findings',financePanel(a))+details('Connected original records',recordSummary(a.records))+
 details('Declared relationship graph',table(['Relationship / purpose','From exact identity','To exact identity'],a.graph.edges.slice(0,100).map(e=>[esc(e.relation)+' / '+esc(e.purpose),esc(e.from),esc(e.to)]))+exact('Every edge and declared cycle',a.graph))+
 details('Original document byte bindings',table(['Document record','Binding','Original file','Whole bytes'],a.documents.map(d=>[esc(d.key),esc(d.state),esc(d.actual?.filename||d.expected.filename||''),d.actual?String(d.actual.bytes)+' B<br><code>'+esc(d.actual.sha256)+'</code>':esc(d.expected.fileId)])))+
 details('Source permission assertions', '<p>These records preserve the source policy. They do not authorize access to this offline file.</p>'+recordSummary(a.permissions.records)+exact('Original permission basis',a.permissions.basis))+
 details('Source history records',recordSummary(a.history.records)+exact('Original history basis',a.history.basis));
}
function targetPreview(assessment,prefix,downloadable=false){
 return '<p>Tables: <strong>'+assessment.summary.tables+'</strong>; prepared rows: <strong>'+assessment.summary.rows+'</strong>; errors: <strong>'+assessment.summary.errors+'</strong>; current preparation ready: <strong>'+esc(String(assessment.ready))+'</strong>; frozen source stale: <strong>'+esc(String(assessment.stale))+'</strong>.</p>'+
 table(['Severity','Finding','Original context'],assessment.issues.map(i=>[esc(i.severity),esc(i.code)+'<br>'+esc(i.message),exact('Complete finding',i)]))+
 assessment.tables.map(t=>details('Table '+t.id+' · '+t.rows.length+' full rows',table(['Prepared row / original identity',...t.headers.map((h,i)=>i+' · '+h)],t.rows.slice(0,50).map(r=>[esc(r.rowId)+'<br>'+identityText(r.sourceIdentity),...r.cells.map(missing)]))+
 '<p>'+t.rows.length+' rows; '+t.bytes+' bytes. Every row and original witness remains in the full edition.</p>'+
 (downloadable?'<button type="button" data-prepared-table="'+esc(t.id)+'">Download complete frozen CSV</button>':'')+
 exact('Every original row and complete table',t))).join('');
}
function returnSummary(returned){
 const c=returned.comparison;return '<h3>'+esc(returned.id)+'</h3><p>Prepared edition '+esc(returned.preparationId)+'. Original reference: '+esc(returned.submissionReference||'(not supplied)')+'.</p>'+
 table(['Observed measure','Count'],Object.entries(c.summary).map(([k,v])=>[esc(label(k)),String(v)]))+
 '<p>Native acceptance: '+esc(c.nativeAcceptance)+'. Permission enforcement: '+esc(c.permissionEnforcement)+'. These remain separate from the observed cell comparison.</p>'+
 c.tables.map(t=>details('Actual returned table '+t.tableId,table(['State','Exact key','Changed / unreported cells','Original evidence'],t.comparisons.slice(0,100).map(row=>[esc(row.state),esc(JSON.stringify(row.key)),table(['Column','Expected exact text','Actual exact text'],row.cells.filter(v=>!v.equal).map(v=>[v.column+' · '+esc(v.header),missing(v.expected),missing(v.actual)])),exact('Full returned rows and source witnesses',row)]))+
 '<p>'+t.comparisons.length+' comparisons retained. Original file '+esc(t.fileId)+' · '+t.bytes+' B.</p>'+exact('Every complete comparison',t))).join('')+
 (c.unreported.length?'<h4>Unreported expected tables</h4>'+table(['Table','Expected rows'],c.unreported.map(t=>[esc(t.tableId),String(t.preparedRows)])):'')+
 exact('Complete original returned edition',returned)+
 '<div class="actions"><button type="button" data-return-json="'+esc(returned.id)+'">Download complete return JSON</button><button type="button" data-return-report="'+esc(returned.id)+'">Download full return report</button></div>';
}

function issueRows(a){return (a.issues||[]).map((issue,index)=>[esc(issue.severity),esc(issue.code),esc(issue.explanation||issue.message||issue.note||''),esc(issue.role||''),exact('Complete original witnesses',issue),'<button type="button" data-finding="'+index+'">Open source witness</button>']);}
views.review=()=>{
  if(!S.ws.selections.length)return card('Findings and exact review','<p>Save an explicit complete scope first.</p>');
  const a=analysis();return card('Complete source findings',scopeChooser('review-scope')+'<div class="facts">'+[['Errors',a.summary.errors],['Warnings',a.summary.warnings],['Source rows',a.summary.rows],['Unique records',a.summary.records]].map(([name,count])=>'<div class="fact"><strong>'+esc(count)+'</strong><span>'+name+'</span></div>').join('')+'</div><p>Structural readiness: <strong>'+esc(String(a.structurallyReady))+'</strong>. Frozen scope stale: <strong>'+esc(String(a.stale))+'</strong>. Harbour/financial/supplier acceptance: '+esc(a.semanticAcceptance)+'.</p>'+table(['Severity','Code','Finding','Role','Full witness','Inspect'],issueRows(a))+sourceStructure(a)+exact('Complete role coverage and original selected records',a.roles)+exact('Complete selected source analysis',a)+'<div class="actions"><button id="analysis-json">Download complete analysis</button><button id="analysis-html">Download readable source report</button></div>')+card('Attributed review',form('review-form',select('review-decision','Decision',['needs-work','accepted'])+area('review-note','Review reasoning and unresolved source / supplier meaning')+'<p>Accepted means this exact selected source is structurally coherent and retains the current profile selection. Operating and financial findings keep their own explicit states. Harbour decisions, financial signoff and supplier acceptance retain their own actual authority.</p>','Save review edition'))+card('All original reviews',table(['Review','Scope','Decision','Original'],S.ws.reviews.map(review=>[esc(review.id),esc(review.selectionId),esc(review.decision),exact('Complete original review',review)])));
};
binders.review=()=>{
  bindScopeChooser('review-scope');
  on('analysis-json',async()=>download('Harbour_Source_Analysis.json',pretty(analysis()),'application/json'));
  on('analysis-html',async()=>download('Harbour_Source_Report.html',Engine.renderReport(S.ws,{selectionId:currentScope()}),'text/html'));
  for(const button of document.querySelectorAll('[data-finding]'))button.onclick=()=>act(async()=>{const issue=analysis().issues[Number(button.dataset.finding)],witness=issue.witnesses?.[0]||issue.sourceRows?.[0];if(!witness?.sourceId||!witness?.rowId){notice('This finding has no single row to correct. Its complete original context is visible in the witness disclosure.');return;}S.selection.source=witness.sourceId;S.selection.row=witness.rowId;S.selection.column=0;S.selection.section='records';const rows=Engine.sourceRows(S.ws,witness.sourceId).rows;S.page=Math.floor(Math.max(0,rows.findIndex(r=>r.id===witness.rowId))/50);await saveSelectionDraft();render();});
  bindSubmit('review-form',async(fields,unused,formId)=>{await mutate('saveReview',{selectionId:currentScope(),decision:fields['review-decision'],note:fields['review-note']},formId);render();notice('Saved review against that complete frozen scope.');});
};

function defaultTargetTables(){
  const mappingId='SELECT_ACTUAL_MAPPING',template='SELECT_ACTUAL_TEMPLATE';
  return [{id:'target-table-1',mappingId,templateFileId:template,keyColumns:[0],columns:{'0':{keyIndex:0}},referenceBindings:[]}];
}
views.contract=()=>{
  if(!S.ws.selections.length)return card('Actual supplier contract','<p>Save an explicit source scope first, and retain the original supplier workbook/template and field dictionary.</p>');
  return card('Select the supplied target contract',scopeChooser('contract-scope')+'<p>CSV is the selected staging format. An ODF/Excel/MS Project workbook remains a complete original; its permitted load route and exact target semantics come from the supplier. This workspace performs no vendor writes.</p>'+form('contract-form',input('contract-title','Contract / workbook edition title')+select('contract-authority','Original authority',['supplier-provided','authored-example'])+checks('contract-original','Actual template, dictionary and return-contract files',options(S.ws.files.map(f=>({...f,display:f.filename||f.name||f.id})),'display'),[])+area('contract-tables','Complete target tables',pretty(defaultTargetTables()),'Each actual CSV template supplies its exact ordered headings. Every target column needs one explicit selector. Keys, source mapping and reference bindings use actual original identities.',true)+area('contract-crosswalks','Original source-to-target key crosswalks','[]','Each crosswalk selects a retained actual CSV, exact source role/namespace, original key columns and target columns. No native IDs are generated.',true)+area('contract-note','Supplier semantics, missing contracts and operator reasoning'),'Save target contract'))+card('Target selector definitions',table(['Selector','Meaning'],[['<code>{"field":"label"}</code>','Exact selected mapped source field'],['<code>{"keyIndex":0}</code>','One original opaque key component'],['<code>{"column":2}</code>','Exact original/effective CSV position'],['<code>{"constant":""}</code>','Deliberate exact constant, including a blank'],['<code>{"referenceId":"original-ref","keyIndex":0}</code>','Explicit original reference key component'],['<code>{"crosswalkId":"received-crosswalk","index":0}</code>','Actual original crosswalk target value']]))+(S.ws.contracts.length?card('Current target assessment',select('assess-contract','Exact target contract',options(S.ws.contracts,'title'),S.selection.contract||S.ws.contracts.at(-1).id)+targetPreview(Engine.assessContract(S.ws,{contractId:S.selection.contract||S.ws.contracts.at(-1).id}),'contract')+'<button type="button" id="target-assessment-json">Download full target assessment</button>'):'')+card('Every retained target edition',S.ws.contracts.length?table(['Contract','Authority','Scope','Full original selection'],S.ws.contracts.map(contract=>[esc(contract.title||contract.id),esc(contract.authority),esc(contract.selectionId),exact('Complete target contract',contract)])):'<p>No target contract selected.</p>');
};
binders.contract=()=>{bindScopeChooser('contract-scope');const selected=$('assess-contract');if(selected)selected.onchange=()=>act(async()=>{S.selection.contract=selected.value;await saveSelectionDraft();render();});on('target-assessment-json',async()=>download('Harbour_Target_Assessment.json',pretty(Engine.assessContract(S.ws,{contractId:S.selection.contract||S.ws.contracts.at(-1).id})),'application/json'));bindSubmit('contract-form',async(fields,unused,formId)=>{const result=await mutate('saveContract',{selectionId:currentScope(),title:fields['contract-title'],authority:fields['contract-authority'],sourceFileIds:listIds(fields,'contract-original'),tables:parsed(fields['contract-tables'],'Target tables'),crosswalks:parsed(fields['contract-crosswalks'],'Crosswalks'),note:fields['contract-note']},formId);S.selection.contract=result.receipt.result.contractId;render();notice('Saved actual selected target contract '+S.selection.contract+'.');});};
function currentPreparation(){return S.ws.preparations.find(p=>p.id===(S.selection.preparation||S.ws.preparations.at(-1)?.id))||null;}
function defaultReturnTables(preparation){const contract=S.ws.contracts.find(c=>c.id===preparation?.contractId);return (contract?.tables||[]).map(table=>({tableId:table.id,fileId:'SELECT_ACTUAL_RETURNED_CSV',columns:Object.fromEntries(Object.keys(table.columns||{}).map(index=>[index,Number(index)]))}));}
views.returns=()=>{
  const prep=currentPreparation();let html=card('Freeze the full prepared edition',form('prepare-form',select('prepare-contract','Selected target contract',options(S.ws.contracts.map(c=>({...c,display:c.title||c.id})),'display'),S.selection.contract||S.ws.contracts.at(-1)?.id||'')+select('prepare-review','Accepted original source review',options(S.ws.reviews.filter(r=>r.decision==='accepted')),S.selection.review||S.ws.reviews.filter(r=>r.decision==='accepted').at(-1)?.id||'')+area('prepare-note','Prepared delivery context')+'<p>The accepted review must still match the current selected source. Preparation preserves every generated row and its original scope. The supplier performs the sanctioned load.</p>','Freeze prepared output'));
  if(prep){html+=card('Complete selected prepared output',select('return-preparation','Prepared edition',options(S.ws.preparations),prep.id)+targetPreview(prep.assessment,'prepared',true)+exact('Every prepared output row, binding and original analysis',prep)+'<div class="actions"><button id="prepared-json">Download full prepared edition</button><button id="prepared-report">Download complete prepared report</button></div>')+card('Receive actual supplied data',form('return-form','<p>Retain each complete returned CSV under Original files first. Map every expected destination column to its actual returned occurrence. Use null for an unreported non-key field; omitted tables remain visible as unreported.</p>'+area('return-tables','Actual returned tables and column mapping',pretty(defaultReturnTables(prep)),'Exact tableId, retained fileId and numeric column mappings. Include the received original response, native outcome and version columns in the retained file.',true)+input('return-reference','Actual submission reference, if supplied')+area('return-note','Return provenance and interpretation'),'Reconcile actual returned files'));}
  html+=card('Every retained return',S.ws.returns.length?S.ws.returns.map(returnSummary).join(''):'<p>No actual return selected.</p>');return html;
};
binders.returns=()=>{
  for(const button of document.querySelectorAll('[data-prepared-table]'))button.onclick=()=>act(async()=>{const t=currentPreparation().assessment.tables.find(t=>t.id===button.dataset.preparedTable);download('table-'+t.sha256.slice(0,24)+'.csv',t.text,'text/csv;charset=utf-8');});
  for(const button of document.querySelectorAll('[data-return-json]'))button.onclick=()=>act(async()=>{const r=S.ws.returns.find(r=>r.id===button.dataset.returnJson);download('Harbour_Return_'+r.revision+'.json',pretty(r),'application/json');});
  for(const button of document.querySelectorAll('[data-return-report]'))button.onclick=()=>act(async()=>{const r=S.ws.returns.find(r=>r.id===button.dataset.returnReport),p=S.ws.preparations.find(p=>p.id===r.preparationId);download('Harbour_Return_Report.html',Engine.renderReport(S.ws,{selectionId:p.selectionId,preparationId:p.id,returnId:r.id}),'text/html');});
  const selected=$('return-preparation');if(selected)selected.onchange=()=>act(async()=>{S.selection.preparation=selected.value;await saveSelectionDraft();render();});
  bindSubmit('prepare-form',async(fields,unused,formId)=>{const result=await mutate('prepareTarget',{contractId:fields['prepare-contract'],reviewId:fields['prepare-review'],note:fields['prepare-note']},formId);S.selection.preparation=result.receipt.result.preparationId;render();notice('Retained complete prepared edition '+S.selection.preparation+'.');});
  bindSubmit('return-form',async(fields,unused,formId)=>{const prep=currentPreparation(),result=await mutate('recordReturn',{preparationId:prep.id,tables:parsed(fields['return-tables'],'Returned tables'),submissionReference:fields['return-reference'],note:fields['return-note']},formId);S.selection.return=result.receipt.result.returnId;render();notice('Retained actual returned files and their complete comparison.');});
  on('prepared-json',async()=>download('Harbour_Prepared_Edition.json',pretty(currentPreparation()),'application/json'));
  on('prepared-report',async()=>{const prep=currentPreparation(),contract=S.ws.contracts.find(c=>c.id===prep.contractId);download('Harbour_Prepared_Report.html',Engine.renderReport(S.ws,{selectionId:contract.selectionId,preparationId:prep.id}),'text/html');});
};
views.history=()=>card('Original operation history',table(['Revision','Operation','Actor','Original result'],S.ws.operations.map(op=>[esc(op.revision),esc(op.kind)+'<br><small>'+esc(op.id)+'</small>',esc(op.actor)+'<br><small>'+esc(op.at)+'</small>',exact('Complete original operation',op)])))+card('Unfinished forms and independent tabs','<p>Each page has its own unfinished writing. Opening a prior page copy can retain those exact values without replacing another tab. Stale forms keep their original revision until explicitly reviewed.</p><div id="draft-sets">Loading retained unfinished values…</div>')+card('Current complete recovery',exact('This tab’s unfinished forms',S.drafts)+'<div class="actions"><button id="history-json">Download complete working JSON</button><button id="history-raw">Download raw unfinished values</button><button id="history-copy">Keep an independent working copy</button></div>');
binders.history=()=>{
  const key=S.key;Store.draftSets(key).then(sets=>{if(!$('draft-sets')||S.key!==key)return;$('draft-sets').innerHTML=table(['Tab edition','Saved','Forms','Recover'],sets.map(set=>[esc(set.tab),esc(set.updatedAt),String(Object.keys(set.drafts).length),'<button type="button" data-draft-tab="'+esc(set.tab)+'">Keep in independent copy</button>']));for(const button of document.querySelectorAll('[data-draft-tab]'))button.onclick=()=>act(async()=>{const set=sets.find(x=>x.tab===button.dataset.draftTab),copy=id('harbour-copy');await Store.createCopy(copy,S.ws,S.selection,tab,set.drafts);await useCopy(copy);notice('Retained that tab’s complete unfinished values in a separate working copy.');});if(S.busy)busy(true);}).catch(error=>notice(error.message,true));
  on('history-json',async()=>download('Harbour_Working_Recovery.json',pretty(record()),'application/json'));
  on('history-raw',async()=>rawDrafts());on('history-copy',async()=>{const key=id('harbour-copy');await Store.createCopy(key,S.ws,S.selection,tab,S.drafts);await useCopy(key);notice('Saved an independent complete copy.');});
};
function rawDrafts(){download('Harbour_Unfinished_Values.json',pretty({schema:'commons.harbour-source-unfinished.v1',workspaceId:S.ws?.id||null,copyId:S.key,baseRevision:S.ws?.revision??null,selection:S.selection,drafts:S.drafts}),'application/json');}
$('global-home').addEventListener('click',()=>act(()=>chooseSection('workspace')));
$('global-raw-drafts').addEventListener('click',rawDrafts);
(async()=>{
  try{
    if(boot.record){
      const incoming=Portable.parseRecovery(pretty(boot.record)),key=incoming.copyId||boot.copyId||id('harbour-copy'),current=await Store.readCopy(key);
      if(!current){await Store.createCopy(key,incoming.workspace,incoming.selection,tab,incoming.drafts);await useCopy(key);}
      else{
        const relation=Portable.compare(current.workspace,incoming.workspace);
        if(relation==='identical'||relation==='incoming_ancestor')await useCopy(key,incoming.drafts,incoming.selection);
        else{const independent=id('harbour-copy');await Store.createCopy(independent,incoming.workspace,incoming.selection,tab,incoming.drafts);await useCopy(independent);notice('The received file is preserved as an independent copy alongside the existing saved work.');}
      }
    }else render();
  }catch(error){notice('The complete working file could not be opened: '+error.message,true);$('harbour-app').innerHTML='<section class="card"><h2>Retain this original file</h2><p>'+esc(error.message)+'</p><p>The complete original bootstrap and saved browser copies remain available. Use the original unmodified file or a complete working JSON export.</p><button id="startup-download">Download exact embedded working record</button></section>';$('startup-download').onclick=()=>download('Original_Embedded_Working_Record.json',pretty(boot.record),'application/json');}
  finally{busy(false);}
})();
